export const getInvoices = async (req, res) => {
  try {
    const invoices = await getCollection('invoices')
      .find({ firmId: req.user._id })
      .sort({ createdAt: -1 })
      .toArray();
    res.json(invoices);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch invoices' });
