    let list = Array.isArray(clients) ? clients : [];

    if (categoryFilter !== 'All') {
      list = list.filter(c => c.itProfile?.category === categoryFilter);
    }

    if (statusColFilter !== 'All') {
      list = list.filter(c => c.status === statusColFilter);
